const cfg = $('Maintenance Settings').first().json;
const zone = 'Asia/Kolkata';
const now = DateTime.now().setZone(zone);
const today = now.toFormat('yyyy-MM-dd');
const NL = String.fromCharCode(10);

function parseTime(v) {
  const s = String(v || '').trim();
  if (!s) return null;
  let d = DateTime.fromISO(s, { zone });
  if (!d.isValid) d = DateTime.fromFormat(s, 'yyyy-MM-dd HH:mm', { zone });
  return d.isValid ? d : null;
}
const isRow = j => j && Object.keys(j).length > 0;
const variations = $('Read Content Variations').all().map(i => i.json).filter(j => isRow(j) && j.Content_ID);
const topics = $('Read Topic Queue').all().map(i => i.json).filter(j => isRow(j) && (j.Topic || j.Post_ID));
const destOf = r => String(r.Destination || '').toLowerCase().startsWith('comp') ? 'Company' : 'Personal';

const byStatus = {};
for (const r of variations) {
  const s = String(r.Review_Status || '(blank)');
  byStatus[s] = (byStatus[s] || 0) + 1;
}

const fixes = [];
const stuck = variations.filter(r => {
  if (String(r.Review_Status) !== 'Publishing') return false;
  const t = parseTime(r.Published_At) || parseTime(r.Last_Updated);
  return !t || now.diff(t, 'minutes').minutes > Number(cfg.stuck_publishing_minutes || 60);
});
for (const r of stuck) {
  fixes.push({
    row_number: r.row_number,
    Review_Status: 'Publish Failed',
    Status_Note: 'Stuck in Publishing since ' + (r.Published_At || 'unknown') + '. Check LinkedIn first - if it is not live, set status back to Approved - Ready to Schedule.',
    Last_Updated: now.toFormat('yyyy-MM-dd HH:mm')
  });
}

const waiting = ['Pending Review', 'Awaiting Publisher', 'Awaiting Admin'];
const stale = variations.filter(r => {
  if (!waiting.includes(String(r.Review_Status))) return false;
  const t = parseTime(r.Last_Updated) || parseTime(r.Generated_At);
  return t && now.diff(t, 'hours').hours > Number(cfg.stale_review_hours || 24);
});
const blocked = variations.filter(r => /^blocked|^publish failed|^revision requested - notes missing/i.test(String(r.Review_Status || '')));

const approved = { Personal: 0, Company: 0 };
for (const r of variations) if (String(r.Review_Status) === 'Approved - Ready to Schedule') approved[destOf(r)]++;
let upcoming = 0;
for (let d = 1; d <= 7 && upcoming < 5; d++) {
  const day = now.plus({ days: d });
  if (day.weekday <= 5) upcoming++;
}
const publishedToday = variations.filter(r => String(r.Review_Status) === 'Published' && String(r.Published_At || '').slice(0, 10) === today);
const weekStart = now.startOf('week');
const publishedWeek = variations.filter(r => {
  if (String(r.Review_Status) !== 'Published') return false;
  const t = parseTime(r.Published_At);
  return t && t >= weekStart;
});

const topicStatus = {};
for (const t of topics) {
  const s = String(t.Status || '(new / unprocessed)');
  topicStatus[s] = (topicStatus[s] || 0) + 1;
}
const stuckTopics = topics.filter(t => {
  if (t.Status && t.Status !== 'Processing') return false;
  if (!t.Post_ID) return false;
  const p = parseTime(t.Processed_At);
  return !p || now.diff(p, 'hours').hours > Number(cfg.stuck_topic_hours || 2);
});

const lines = [];
lines.push('LinkedIn content - daily health report (' + now.toFormat('ccc d LLL yyyy, HH:mm') + ' IST)');
lines.push('');
lines.push('Published today: ' + publishedToday.length + ' | This week: ' + publishedWeek.length);
lines.push('Approved and waiting - Personal: ' + approved.Personal + ', Company: ' + approved.Company + ' (next ' + upcoming + ' weekday slots each)');
if (approved.Personal < upcoming) lines.push('  Personal pipeline short by ' + (upcoming - approved.Personal) + ' post(s)');
if (approved.Company < upcoming) lines.push('  Company pipeline short by ' + (upcoming - approved.Company) + ' post(s)');
lines.push('');
lines.push('Drafts by status: ' + (Object.keys(byStatus).map(k => k + ' ' + byStatus[k]).join(', ') || 'none'));
lines.push('Topics by status: ' + (Object.keys(topicStatus).map(k => k + ' ' + topicStatus[k]).join(', ') || 'none'));
if (stale.length) lines.push('Waiting on approval > ' + cfg.stale_review_hours + 'h (' + stale.length + '): ' + stale.slice(0, 10).map(r => r.Content_ID + ' [' + r.Review_Status + ']').join(', '));
if (blocked.length) lines.push('Blocked or failed (' + blocked.length + '): ' + blocked.slice(0, 10).map(r => r.Content_ID + ' [' + r.Review_Status + ']').join(', '));
if (stuckTopics.length) lines.push('Topics that look stuck (' + stuckTopics.length + '): ' + stuckTopics.slice(0, 10).map(t => t.Topic).join(', '));
if (fixes.length) lines.push('Auto-fixed: ' + fixes.length + ' row(s) stuck in Publishing were marked Publish Failed - check LinkedIn before retrying.');

let db = {};
try { db = $('Database Housekeeping').first().json || {}; } catch (e) { db = {}; }
const dbOk = db && db.spend_today_usd !== undefined && !db.error;
const asList = v => Array.isArray(v) ? v : (typeof v === 'string' && v.trim().startsWith('[') ? JSON.parse(v) : []);
const money = v => '$' + Number(v || 0).toFixed(4);
const overBudget = dbOk ? asList(db.over_budget) : [];
const nearBudget = dbOk ? asList(db.near_budget) : [];
lines.push('');
if (dbOk) {
  lines.push('AI and research spend - today: ' + money(db.spend_today_usd) + ' across ' + (db.topics_charged_today || 0) + ' topic(s) | this week: ' + money(db.spend_week_usd));
  lines.push('Topic slots in use: ' + (db.slots_busy || 0) + ' of 3');
  if (Number(db.slots_freed || 0) > 0) lines.push('Auto-fixed: freed ' + db.slots_freed + ' expired topic slot(s): ' + db.freed_topics);
  if (overBudget.length) lines.push('Over the per-topic budget (' + overBudget.length + '): ' + overBudget.slice(0, 10).map(b => b.post_id + ' ' + money(b.spent_usd) + '/' + money(b.budget_usd)).join(', '));
  if (nearBudget.length) lines.push('Above 80% of budget (' + nearBudget.length + '): ' + nearBudget.slice(0, 10).map(b => b.post_id + ' ' + money(b.spent_usd)).join(', '));
} else {
  lines.push('Database check failed - spend, budgets and topic slots were not checked tonight' + (db.error ? ' (' + String(db.error.message || db.error).slice(0, 150) + ')' : '') + '.');
}
const slotFixes = dbOk ? Number(db.slots_freed || 0) : 0;
if (!stale.length && !blocked.length && !stuckTopics.length && !fixes.length && !slotFixes && !overBudget.length && dbOk) lines.push('No issues found.');

return [{ json: { report: lines.join(NL), report_chat: String(cfg.report_chat || ''), fixes, fix_count: fixes.length } }];
